/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "skippedRecordRulesCount",
		value: event.payload.model.layoutQuery.count || 0
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  try {
    const activityState = api.data.playbook_activity_ui.playbookCardProperties.activityState.value;
    const flag = (['3', '4'].includes(api.state.upgradePreviewExecTrackerState)); //0-Pending, 1-Running, 2-Successful, 3-Failed, 4-Cancelled

    return flag ? "margin" : "";
  } catch(e) {
    console.error("Error in adding class", e);
  }
}

targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const isProduction = api.context.props.experienceProperties.environment.value === 'production';
	return {
		event: 'Complete step',
		value: {
			Environment: isProduction ? 'Production' : 'Subproduction',
			Skipped: true,
			Step: 'Review Predicted Skipped Records'
		}
	};
})

